'npc.bram.3': "Uwazaj na gleboka wode za piaskiem.",
'npc.juniper.0': "Witaj! Nasiona na polce, jajka w kieszeni.",
'npc.juniper.1': "Kup tanio, rosnij wysoko. Caly sekret.",
'npc.juniper.2': "Kury niosa, patrzysz czy nie.",
'mail.tip0.from': 'MIRA', 'mail.tip0.sub': 'MADROSC WODY', 'mail.tip0.body': "Drogi farmerze, rosliny pija najlepiej|gdy ziemia nocuje mokra.|Deszcz liczy sie: patrz w niebo!",
'mail.tip1.from': 'BRAM', 'mail.tip1.sub': 'SKALY I SKARB', 'mail.tip1.body': "Ametysty w jasnych skalach|za piaskiem przy stawie.|Wez kilof i energie.",
'mail.tip2.from': 'JUNIPER', 'mail.tip2.sub': 'DZIEN TARGU', 'mail.tip2.body': "Sklep placi pelna cene za wszystko|co uprawisz lub wykopiesz.|Nasiona codziennie.",
'mail.tip3.from': 'POCZTA SUNVALE', 'mail.tip3.sub': 'ULOTKA', 'mail.tip3.body': "KURY NIOSA JAJKA NOCA.|GIELASKAJ JE DLA PRZYJAZNI.|KURNIK MIESCI SZESC KUR.",
'mail.tip4.from': 'MIRA', 'mail.tip4.sub': 'DYNIOWY SEZON', 'mail.tip4.body': "Dynia rosnie dziewiec dni ale|daje ogromna cene.|Sadz wczesnie i zapomnij.",
'mail.tip5.from': 'BRAM', 'mail.tip5.sub': 'PIENKI', 'mail.tip5.body': "Sciete drzewa zostawia pnie.|Odrastaja w pare dni,|las zawsze wraca.",
'mail.tip6.from': 'JUNIPER', 'mail.tip6.sub': 'PELNY ZOLADEK', 'mail.tip6.body': "Jedzenie daje energie.|Miej jagode w kieszeni|by nigdy nie zemdlec.",
'mail.tip7.from': 'POCZTA SUNVALE', 'mail.tip7.sub': 'POGODA', 'mail.tip7.body': "Burza moczy wszystko naraz.|Slonce suszy ziemie.|Podlewaj wg prognozy.",
'mail.tip8.from': 'BRAM', 'mail.tip8.sub': 'DAJ PREZENT', 'mail.tip8.body': "Trzymaj przedmiot i nacisnij G przy|mieszkancu. Plony daja serca!|Ulubione daja najwiecej!",
'mail.tip9.from': 'MIRA', 'mail.tip9.sub': 'O SKRZYNCE', 'mail.tip9.body': "Prosby przychodza tu|kazdego ranka. Dostarcz co|chca, a zloto twoje.",
'mail.req0.from': 'MIRA', 'mail.req0.sub': 'MALA PRZYSUGA', 'mail.req0.body': "Trzy rzepy prosze?|Robie gulasz dla Brama.|Dobrze zaplace.",
'mail.req1.from': 'BRAM', 'mail.req1.sub': 'PLOT', 'mail.req1.body': "Moj plot przy stawie pada.|Wyslij osiem drewna, naprawie.",
'mail.req2.from': 'JUNIPER', 'mail.req2.sub': 'ZAMOWIENIE', 'mail.req2.body': "Cztery swieze jajka, jesli masz.|Rannek wymaga pieczenia|zloto czeka.",
'mail.req3.from': 'MIRA', 'mail.req3.sub': 'DZEM', 'mail.req3.body': "Piec dzikich jagod prosze.|Robie dzem na zime|wymienie za zloto.",
'mail.req4.from': 'BRAM', 'mail.req4.sub': 'SCIEZKA', 'mail.req4.body': "Sciezka wymaga naprawy.|Wyslij osiem kamienia, cala|wioska dziekuje.",
'mail.req5.from': 'JUNIPER', 'mail.req5.sub': 'ZUPA', 'mail.req5.body': "Zupa marchewkowa w tym tygodniu.|Cztery marchwie od ciebie|zysk twoj.",
'mail.req6.from': 'MIRA', 'mail.req6.sub': 'PIKNIK', 'mail.req6.body': "Trzy dojrzale truskawki prosze.|Piknik przy stawie|place top zloto.",
'mail.req7.sub': 'KLEJNOT', 'mail.req7.body': "Jeden ametyst, handluje|z wedrowcem. Wyslij, przyjacielu!",
'gift.0': 'DZIEKUJE! TEGO CHCIALAM.', 'gift.1': 'JAK MILO!', 'gift.2': 'MASZ DOBRE SERCE.', 'gift.3': 'ZACHOWAM TO. DZIEKUJE!',
'mail.ms0.sub': 'DROBIAZG', 'mail.ms0.body': "Byles mily ostatnio,|zachowalam nasiona.|Posadz i pomysl o mnie!",
'mail.ms1.sub': 'DZIEKUJE', 'mail.ms1.body': "Dzieki od wioski.|Marchew rosnie slodka.|Nie sprzedawaj wszystkich.",
'mail.ms2.sub': 'DLA PRZYJACIELA', 'mail.ms2.body': "Rzadko mowimy:|jestes dobrym przyjacielem Sunvale.|Wez te nasiona.",
